public class NDS32Analyzer : ConstantPropagationAnalyzer {
	private static string PROCESSOR_NAME = "NDS32";
	
	private static readonly string RECOVER_GP_OPTION_NAME = "Recover global GP register writes";
	private static readonly string RECOVER_GP_OPTION_DESCRIPTION = "Reads the global GP value from the symbol _SDA_BASE_";
	private static readonly bool RECOVER_GP_OPTION_DEFAULT_VALUE = true;
	
	
	//private boolean recoverSwitchTables = SWITCH_OPTION_DEFAULT_VALUE;
	private bool recoverGp = RECOVER_GP_OPTION_DEFAULT_VALUE;

	private Address gpAssumptionValue = null;

	private Register gp;

	public NDS32Analyzer() : base(PROCESSOR_NAME)
    {
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		bool canAnalyze = program.getLanguage().getProcessor().equals(
			Processor.findOrPossiblyCreateProcessor(PROCESSOR_NAME));

		if (!canAnalyze) {
			return false;
		}

		gp = program.getRegister("gp");
		
		return true;
	}

	/* @Override */
	public void optionsChanged(Options options, Program program) {
		base.optionsChanged(options, program);

		options.registerOption(RECOVER_GP_OPTION_NAME, recoverGp, null,
				RECOVER_GP_OPTION_DESCRIPTION);
		recoverGp = options.getBoolean(RECOVER_GP_OPTION_NAME, recoverGp);
	}
	
	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {
		gpAssumptionValue = null;

		checkForGlobalGP(program, set, monitor);

		return base.added(program, set, monitor, log);
	}

	/**
	 * Check for a global GP register symbol or discovered symbol
	 * @param program
	 * @param set
	 * @param monitor
	 */
	private void checkForGlobalGP(Program program, AddressSetView set, TaskMonitor monitor) {
		if (!recoverGp) {
			return;
		}

		Symbol symbol = SymbolUtilities.getLabelOrFunctionSymbol(program, "_SDA_BASE_",
			err => Msg.error(this, err));
		if (symbol != null) {
			gpAssumptionValue = symbol.getAddress();
			return;
		}

		// TODO : if the symbol doesn't exist, check manually... somewhere else
		
		return;
	}

	/* @Override */
	public AddressSetView flowConstants(Program program, Address flowStart,
			AddressSetView flowSet, SymbolicPropogator symEval, TaskMonitor monitor)
    {
		
		// get the function body
		Function func = program.getFunctionManager().getFunctionContaining(flowStart);

		AddressSet coveredSet = new AddressSet();
		
		Address currentGPAssumptionValue = gpAssumptionValue;

		// TODO : copypaste more code from MipsAddressAnalyzer to see if gp is written and act accordingly
		if (func != null) {
			flowStart = func.getEntryPoint();
			if (currentGPAssumptionValue != null) {
				ProgramContext programContext = program.getProgramContext();
				RegisterValue gpVal = programContext.getRegisterValue(gp, flowStart);
				if (gpVal == null || !gpVal.hasValue()) {
					gpVal = new RegisterValue(gp,
						BigInteger.valueOf(currentGPAssumptionValue.getOffset()));
					try {
						program.getProgramContext().setRegisterValue(func.getEntryPoint(),
							func.getEntryPoint(), gpVal);
					}
					catch (ContextChangeException e) {
						throw new AssertException("unexpected", e); // only happens for context register
					}
				}
			}
		}

		ContextEvaluator eval = new _Anon_ConstantPropagationContextEvaluator_1(monitor, trustWriteMemOption);
		
		AddressSet resultSet = symEval.flowConstants(flowStart, null, eval, true, monitor);

		// Add in any addresses we should assume got covered
		//   These addresses are put on because we had to stop analysis due to an unknown register value
		resultSet.add(coveredSet);

		return resultSet;
	}
	

	internal class _Anon_ConstantPropagationContextEvaluator_1 : ConstantPropagationContextEvaluator
	{
		public _Anon_ConstantPropagationContextEvaluator_1() : @base(monitor, trustWriteMemOption) {}

			/* @Override */
			public bool evaluateDestination(VarnodeContext context, Instruction instruction) {
				FlowType flowtype = instruction.getFlowType();
				if (!flowtype.isJump()) {
					return false;
				}

				return false;
			}
		
	}

}
